import { tv, type VariantProps } from "@/lib/beton/tv";

/**
 * The frame every marketing block sits in: full width, generous padding, and a
 * centred column that never gets wider than the measure.
 */
export const section = tv({
  slots: {
    root: "w-full",
    inner: "mx-auto flex w-full flex-col px-4 sm:px-6",
    header: "flex flex-col gap-4",
    eyebrow: "font-mono text-xs font-bold tracking-widest uppercase",
    title: "font-display font-black tracking-tight text-balance text-foreground",
    description: "max-w-prose text-pretty text-foreground",
    actions: "flex flex-wrap items-center gap-3 pt-2",
  },
  variants: {
    size: {
      sm: { inner: "max-w-5xl gap-8 py-12", title: "text-h3", description: "text-base" },
      md: { inner: "max-w-6xl gap-12 py-16", title: "text-h2", description: "text-lg" },
      lg: { inner: "max-w-7xl gap-16 py-24", title: "text-h1", description: "text-xl" },
    },
    align: {
      start: { header: "items-start text-left" },
      center: { header: "items-center text-center", actions: "justify-center" },
    },
    surface: {
      paper: { root: "bg-surface" },
      raised: { root: "bg-raised" },
      accent: { root: "bg-secondary" },
      ink: { root: "bg-ink text-paper" },
    },
    bordered: {
      true: { root: "border-y-3 border-border" },
    },
  },
  defaultVariants: {
    size: "md",
    align: "start",
    surface: "paper",
    bordered: false,
  },
});

export type SectionVariants = VariantProps<typeof section>;

import { section, type SectionVariants } from "@/lib/beton/recipes/section.recipe";
import { useId, type ComponentProps, type ReactNode } from "react";

export interface SectionProps extends Omit<ComponentProps<"section">, "title">, SectionVariants {
  /** The heading of the section. Every landmark needs one. */
  title?: ReactNode;
  /** A short line above the heading. */
  eyebrow?: ReactNode;
  /** A paragraph under the heading. */
  description?: ReactNode;
  /** Buttons under the text. */
  actions?: ReactNode;
  /** The heading level. Defaults to h2, which is right inside a page with one h1. */
  headingLevel?: 2 | 3 | 4;
}

/**
 * The frame every marketing block sits in: a named landmark, a heading, and a
 * centred column that never gets wider than the measure.
 */
export function Section({
  size = "md",
  align = "start",
  surface = "paper",
  bordered = false,
  title,
  eyebrow,
  description,
  actions,
  headingLevel = 2,
  className,
  children,
  ...props
}: SectionProps) {
  const styles = section({ size, align, surface, bordered });
  const id = useId();
  const Heading = `h${headingLevel}` as const;

  return (
    <section
      {...props}
      aria-labelledby={title ? `${id}-title` : props["aria-labelledby"]}
      data-surface={surface}
      className={styles.root({ class: className })}
    >
      <div className={styles.inner()}>
        {title || description || eyebrow ? (
          <div className={styles.header()}>
            {eyebrow ? <p className={styles.eyebrow()}>{eyebrow}</p> : null}
            {title ? (
              <Heading id={`${id}-title`} className={styles.title()}>
                {title}
              </Heading>
            ) : null}
            {description ? <p className={styles.description()}>{description}</p> : null}
            {actions ? <div className={styles.actions()}>{actions}</div> : null}
          </div>
        ) : null}
        {children}
      </div>
    </section>
  );
}
